def choose_move(observation):
    grid_w = observation.get("grid_width", 0)
    grid_h = observation.get("grid_height", 0)
    self_pos = observation.get("self_position", (0, 0))
    opp_pos = observation.get("opponent_position", (0, 0))
    remaining = observation.get("remaining_resource_count", 0)
    resources = observation.get("resources", [])
    obstacles = observation.get("obstacles", [])
    scores = observation.get("scores", {})
    self_path = observation.get("self_path", [])
    opp_path = observation.get("opponent_path", [])

    x, y = self_pos

    def in_bounds(nx, ny):
        if grid_w and grid_h:
            return 0 <= nx < grid_w and 0 <= ny < grid_h
        return True

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    best = [0, 0]
    best_score = -10**9

    # simple heuristic: move toward closest useful target
    target_positions = []

    for r in resources:
        pos = r.get("position", None)
        if pos is not None:
            target_positions.append(tuple(pos))

    if target_positions:
        closest = min(target_positions, key=lambda p: dist((x, y), p))
        target_positions = [closest]

    # include opponent as a bait but prefer safety
    target_positions += [opp_pos]

    moves = [(-1,0),(1,0),(0,-1),(0,1),(0,0)]
    for dx, dy in moves:
        nx, ny = x + dx, y + dy
        if not in_bounds(nx, ny):
            continue
        blocked = False
        for o in obstacles:
            if (nx, ny) == tuple(o.get("position", (-1,-1))):
                blocked = True
                break
        if blocked:
            continue
        score = 0
        if target_positions:
            d = min(dist((nx, ny), t) for t in target_positions)
            score -= d
        # discourage colliding with opponent
        if (nx, ny) == opp_pos:
            score += 5
        if (nx, ny) == self_pos:
            score += 0
        if score > best_score:
            best_score = score
            best = [dx, dy]

    return best
